1	import { create } from "@bufbuild/protobuf";
2	import { FieldMaskSchema } from "@bufbuild/protobuf/wkt";
3	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
4	import { shortcutServiceClient, userServiceClient } from "@/connect";
5	import useCurrentUser from "@/hooks/useCurrentUser";
6	import { buildUserSettingName } from "@/lib/resource-names";
7	import {
8	  type ListAllUserStatsRequest,
9	  ListAllUserStatsRequestSchema,
10	  User,
11	  UserSetting,
12	  UserSetting_GeneralSetting,
13	  UserSetting_Key,
14	  UserSettingSchema,
15	  UserStats,
16	} from "@/types/proto/api/v1/user_service_pb";
17	
18	const BATCH_GET_USERS_LIMIT = 100;
19	type ListAllUserStatsQuery = Pick<ListAllUserStatsRequest, "state" | "filter">;
20	
21	// Query keys factory
22	export const userKeys = {
23	  all: ["users"] as const,
24	  details: () => [...userKeys.all, "detail"] as const,
25	  detail: (name: string) => [...userKeys.details(), name] as const,
26	  stats: () => [...userKeys.all, "stats"] as const,
27	  userStats: (name: string) => [...userKeys.stats(), name] as const,
28	  allUserStats: (request: Partial<ListAllUserStatsQuery>) => [...userKeys.stats(), "all", request] as const,
29	  currentUser: () => [...userKeys.all, "current"] as const,
30	  shortcuts: () => [...userKeys.all, "shortcuts"] as const,
31	  notifications: () => [...userKeys.all, "notifications"] as const,
32	  byNames: (names: string[]) => [...userKeys.all, "byNames", ...[...names].sort()] as const,
33	  byUsernames: (usernames: string[]) => [...userKeys.all, "byUsernames", ...[...usernames].sort()] as const,
34	};
35	
36	export function useUser(name: string, options?: { enabled?: boolean }) {
37	  return useQuery({
38	    queryKey: userKeys.detail(name),
39	    queryFn: async () => {
40	      const user = await userServiceClient.getUser({ name });
41	      return user;
42	    },
43	    enabled: options?.enabled ?? true,
44	    staleTime: 1000 * 60 * 5, // 5 minutes - user profiles don't change often
45	  });
46	}
47	
48	export function useUserStats(username?: string) {
49	  return useQuery({
50	    queryKey: username ? userKeys.userStats(username) : userKeys.stats(),
51	    queryFn: async () => {
52	      if (!username) {
53	        throw new Error("Username is required");
54	      }
55	      const stats = await userServiceClient.getUserStats({ name: username });
56	      return stats;
57	    },
58	    enabled: !!username,
59	  });
60	}
61	
62	export function useAllUserStats(request: Partial<ListAllUserStatsQuery> = {}, options?: { enabled?: boolean }) {
63	  return useQuery({
64	    queryKey: userKeys.allUserStats(request),
65	    queryFn: async () => {
66	      const { stats } = await userServiceClient.listAllUserStats(create(ListAllUserStatsRequestSchema, request));
67	      return stats;
68	    },
69	    enabled: options?.enabled ?? true,
70	  });
71	}
72	
73	export function useShortcuts() {
74	  return useQuery({
75	    queryKey: userKeys.shortcuts(),
76	    queryFn: async () => {
77	      const { shortcuts } = await shortcutServiceClient.listShortcuts({});
78	      return shortcuts;
79	    },
80	  });
81	}
82	
83	export function useNotifications() {
84	  const currentUser = useCurrentUser();
85	
86	  return useQuery({
87	    queryKey: userKeys.notifications(),
88	    queryFn: async () => {
89	      if (!currentUser?.name) {
90	        return [];
91	      }
92	      const { notifications } = await userServiceClient.listUserNotifications({ parent: currentUser.name });
93	      return notifications;
94	    },
95	    enabled: !!currentUser?.name,
96	    staleTime: 1000 * 30, // 30 seconds - notifications should update frequently
97	  });
98	}
99	
100	export function useTagCounts(forCurrentUser = false) {
101	  const currentUser = useCurrentUser();
102	
103	  return useQuery<UserStats | Record<string, number>, Error, Record<string, number>>({
104	    queryKey:
105	      forCurrentUser && currentUser?.name
106	        ? userKeys.userStats(currentUser.name)
107	        : [...userKeys.stats(), "tagCounts", forCurrentUser ? "current" : "all"],
108	    queryFn: async (): Promise<UserStats | Record<string, number>> => {
109	      if (forCurrentUser) {
110	        if (!currentUser?.name) {
111	          return {};
112	        }
113	        return userServiceClient.getUserStats({ name: currentUser.name });
114	      } else {
115	        // Fetch all user stats
116	        const { stats } = await userServiceClient.listAllUserStats({});
117	
118	        // Aggregate tag counts from all users
119	        const tagCount: Record<string, number> = {};
120	        for (const userStats of stats) {
121	          if (userStats.tagCount) {
122	            for (const [tag, count] of Object.entries(userStats.tagCount)) {
123	              tagCount[tag] = (tagCount[tag] || 0) + count;
124	            }
125	          }
126	        }
127	        return tagCount;
128	      }
129	    },
130	    select: (data) => {
131	      if (forCurrentUser) {
132	        return (data as UserStats).tagCount || {};
133	      }
134	      return data as Record<string, number>;
135	    },
136	    enabled: !forCurrentUser || !!currentUser?.name,
137	    staleTime: 1000 * 60 * 2, // 2 minutes - tags don't change frequently
138	  });
139	}
140	
141	export function useUpdateUser() {
142	  const queryClient = useQueryClient();
143	
144	  return useMutation({
145	    mutationFn: async ({ user, updateMask }: { user: Partial<User>; updateMask: string[] }) => {
146	      const updatedUser = await userServiceClient.updateUser({
147	        user: user as User,
148	        updateMask: create(FieldMaskSchema, { paths: updateMask }),
149	      });
150	      return updatedUser;
151	    },
152	    onSuccess: (updatedUser) => {
153	      queryClient.setQueryData(userKeys.detail(updatedUser.name), updatedUser);
154	      queryClient.invalidateQueries({ queryKey: userKeys.currentUser() });
155	    },
156	  });
157	}
158	
159	export function useDeleteUser() {
160	  const queryClient = useQueryClient();
161	
162	  return useMutation({
163	    mutationFn: async (name: string) => {
164	      await userServiceClient.deleteUser({ name });
165	      return name;
166	    },
167	    onSuccess: (name) => {
168	      queryClient.removeQueries({ queryKey: userKeys.detail(name) });
169	      queryClient.invalidateQueries({ queryKey: userKeys.all });
170	    },
171	  });
172	}
173	
174	// Hook to fetch user settings
175	export function useUserSettings(parent?: string) {
176	  return useQuery({
177	    queryKey: [...userKeys.all, "settings", parent],
178	    queryFn: async () => {
179	      if (!parent) return { settings: [], shortcuts: [] };
180	      const [{ settings }, { shortcuts }] = await Promise.all([
181	        userServiceClient.listUserSettings({ parent }),
182	        shortcutServiceClient.listShortcuts({ parent }),
183	      ]);
184	      return { settings, shortcuts };
185	    },
186	    enabled: !!parent,
187	  });
188	}
189	
190	// Hook to update user setting
191	export function useUpdateUserSetting() {
192	  const queryClient = useQueryClient();
193	
194	  return useMutation({
195	    mutationFn: async ({ setting, updateMask }: { setting: UserSetting; updateMask: string[] }) => {
196	      const updatedSetting = await userServiceClient.updateUserSetting({
197	        setting,
198	        updateMask: create(FieldMaskSchema, { paths: updateMask }),
199	      });
200	      return updatedSetting;
201	    },
202	    onSuccess: () => {
