14	)
15	
16	func convertUserFromStore(user *store.User, viewer *store.User) *v1pb.User {
17		userpb := &v1pb.User{
18			Name:        BuildUserName(user.Username),
19			State:       convertStateFromStore(user.RowStatus),
20			CreateTime:  timestamppb.New(time.Unix(user.CreatedTs, 0)),
21			UpdateTime:  timestamppb.New(time.Unix(user.UpdatedTs, 0)),
22			Role:        convertUserRoleFromStore(user.Role),
23			Username:    user.Username,
24			DisplayName: user.Nickname,
25			AvatarUrl:   user.AvatarURL,
26			Description: user.Description,
27		}
28		if canViewerAccessUserEmail(viewer, user) {
29			userpb.Email = user.Email
30		}
31		// Use the avatar URL instead of raw base64 image data to reduce the response size.
32		if user.AvatarURL != "" {
33			// Check if avatar url is base64 format.
34			_, _, err := extractImageInfo(user.AvatarURL)
35			if err == nil {
36				userpb.AvatarUrl = fmt.Sprintf("/file/%s/avatar", userpb.Name)
37			} else {
38				userpb.AvatarUrl = user.AvatarURL
39			}
40		}
41		return userpb
42	}
43	
44	func canViewerAccessUserEmail(viewer, user *store.User) bool {
45		if viewer == nil || user == nil {
46			return false
47		}
48		return viewer.Role == store.RoleAdmin || viewer.ID == user.ID
49	}
50	
51	func convertUserRoleFromStore(role store.Role) v1pb.User_Role {
52		switch role {
53		case store.RoleAdmin:
54			return v1pb.User_ADMIN
55		case store.RoleUser:
56			return v1pb.User_USER
57		default:
58			return v1pb.User_ROLE_UNSPECIFIED
59		}
60	}
61	
62	func convertUserRoleToStore(role v1pb.User_Role) store.Role {
63		switch role {
64		case v1pb.User_ADMIN:
65			return store.RoleAdmin
66		default:
67			return store.RoleUser
68		}
69	}
70	
71	// extractImageInfo extracts image type and base64 data from a data URI.
72	// Data URI format: data:image/png;base64,iVBORw0KGgo...
73	func extractImageInfo(dataURI string) (string, string, error) {
74		dataURIRegex := regexp.MustCompile(`^data:(?P<type>.+);base64,(?P<base64>.+)`)
75		matches := dataURIRegex.FindStringSubmatch(dataURI)
76		if len(matches) != 3 {
77			return "", "", errors.New("invalid data URI format")
78		}
79		imageType := matches[1]
80		base64Data := matches[2]
81		return imageType, base64Data, nil
82	}
83	
84	// convertSettingKeyToStore converts API setting key to store enum.
85	func convertSettingKeyToStore(key string) (storepb.UserSetting_Key, error) {
86		switch key {
87		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_GENERAL)]:
88			return storepb.UserSetting_GENERAL, nil
89		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_WEBHOOKS)]:
90			return storepb.UserSetting_WEBHOOKS, nil
91		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_TAGS)]:
92			return storepb.UserSetting_TAGS, nil
93		default:
94			return storepb.UserSetting_KEY_UNSPECIFIED, errors.Errorf("unknown setting key: %s", key)
95		}
96	}
97	
98	// convertSettingKeyFromStore converts store enum to API setting key.
99	func convertSettingKeyFromStore(key storepb.UserSetting_Key) string {
100		switch key {
101		case storepb.UserSetting_GENERAL:
102			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_GENERAL)]
103		case storepb.UserSetting_SHORTCUTS:
104			return "SHORTCUTS" // Not defined in API proto
105		case storepb.UserSetting_WEBHOOKS:
106			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_WEBHOOKS)]
107		case storepb.UserSetting_TAGS:
108			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_TAGS)]
109		default:
110			return "unknown"
111		}
112	}
113	
114	func convertUserTagsSettingFromStore(setting *storepb.TagsUserSetting) *v1pb.UserSetting_TagsSetting {
115		if setting == nil {
116			return &v1pb.UserSetting_TagsSetting{Tags: map[string]*v1pb.UserSetting_TagMetadata{}}
117		}
118		tags := make(map[string]*v1pb.UserSetting_TagMetadata, len(setting.Tags))
119		for tag, metadata := range setting.Tags {
120			if metadata == nil {
121				tags[tag] = &v1pb.UserSetting_TagMetadata{}
122				continue
123			}
124			tags[tag] = &v1pb.UserSetting_TagMetadata{
125				BackgroundColor: metadata.GetBackgroundColor(),
126				BlurContent:     metadata.GetBlurContent(),
127			}
128		}
129		return &v1pb.UserSetting_TagsSetting{Tags: tags}
130	}
131	
132	func convertUserTagsSettingToStore(setting *v1pb.UserSetting_TagsSetting) *storepb.TagsUserSetting {
133		if setting == nil {
134			return &storepb.TagsUserSetting{Tags: map[string]*storepb.UserTagMetadata{}}
135		}
136		tags := make(map[string]*storepb.UserTagMetadata, len(setting.Tags))
137		for tag, metadata := range setting.Tags {
138			if metadata == nil {
139				tags[tag] = &storepb.UserTagMetadata{}
140				continue
141			}
142			tags[tag] = &storepb.UserTagMetadata{
143				BackgroundColor: metadata.GetBackgroundColor(),
144				BlurContent:     metadata.GetBlurContent(),
145			}
146		}
147		return &storepb.TagsUserSetting{Tags: tags}
148	}
149	
150	// convertUserSettingFromStore converts store UserSetting to API UserSetting.
151	func convertUserSettingFromStore(storeSetting *storepb.UserSetting, user *store.User, key storepb.UserSetting_Key) *v1pb.UserSetting {
152		if storeSetting == nil {
153			// Return default setting if none exists
154			settingKey := convertSettingKeyFromStore(key)
155			setting := &v1pb.UserSetting{
156				Name: fmt.Sprintf("%s/settings/%s", BuildUserName(user.Username), settingKey),
157			}
158	
159			switch key {
160			case storepb.UserSetting_GENERAL:
161				setting.Value = &v1pb.UserSetting_GeneralSetting_{
162					GeneralSetting: getDefaultUserGeneralSetting(),
163				}
164			case storepb.UserSetting_WEBHOOKS:
165				setting.Value = &v1pb.UserSetting_WebhooksSetting_{
166					WebhooksSetting: &v1pb.UserSetting_WebhooksSetting{
167						Webhooks: []*v1pb.UserWebhook{},
168					},
169				}
170			case storepb.UserSetting_TAGS:
171				setting.Value = &v1pb.UserSetting_TagsSetting_{
172					TagsSetting: &v1pb.UserSetting_TagsSetting{Tags: map[string]*v1pb.UserSetting_TagMetadata{}},
173				}
174			default:
175				return nil
176			}
177			return setting
178		}
179	
180		settingKey := convertSettingKeyFromStore(storeSetting.Key)
181		setting := &v1pb.UserSetting{
182			Name: fmt.Sprintf("%s/settings/%s", BuildUserName(user.Username), settingKey),
183		}
184	
185		switch storeSetting.Key {
186		case storepb.UserSetting_GENERAL:
187			if general := storeSetting.GetGeneral(); general != nil {
188				setting.Value = &v1pb.UserSetting_GeneralSetting_{
189					GeneralSetting: &v1pb.UserSetting_GeneralSetting{
190						Locale:         general.Locale,
191						MemoVisibility: general.MemoVisibility,
192						Theme:          general.Theme,
193					},
194				}
195			} else {
196				setting.Value = &v1pb.UserSetting_GeneralSetting_{
197					GeneralSetting: getDefaultUserGeneralSetting(),
198				}
199			}
200		case storepb.UserSetting_WEBHOOKS:
201			webhooks := storeSetting.GetWebhooks()
202			apiWebhooks := make([]*v1pb.UserWebhook, 0)
203			if webhooks != nil {
204				apiWebhooks = make([]*v1pb.UserWebhook, 0, len(webhooks.Webhooks))
205				for _, webhook := range webhooks.Webhooks {
206					apiWebhook := &v1pb.UserWebhook{
207						Name:             fmt.Sprintf("%s/webhooks/%s", BuildUserName(user.Username), webhook.Id),
208						Url:              webhook.Url,
209						DisplayName:      webhook.Title,
210						SigningSecretSet: webhook.SigningSecret != "",
211					}
212					apiWebhooks = append(apiWebhooks, apiWebhook)
213				}
214			}
215			setting.Value = &v1pb.UserSetting_WebhooksSetting_{
216				WebhooksSetting: &v1pb.UserSetting_WebhooksSetting{
217					Webhooks: apiWebhooks,
218				},
219			}
220		case storepb.UserSetting_TAGS:
221			setting.Value = &v1pb.UserSetting_TagsSetting_{
222				TagsSetting: convertUserTagsSettingFromStore(storeSetting.GetTags()),
223			}
224		default:
225			return nil
226		}
227	
228		return setting
229	}
230	
231	// convertUserSettingToStore converts API UserSetting to store UserSetting.
232	func convertUserSettingToStore(apiSetting *v1pb.UserSetting, userID int32, key storepb.UserSetting_Key) (*storepb.UserSetting, error) {
233		storeSetting := &storepb.UserSetting{
234			UserId: userID,
235			Key:    key,
236		}
237	
238		switch key {
239		case storepb.UserSetting_GENERAL:
240			if general := apiSetting.GetGeneralSetting(); general != nil {
241				storeSetting.Value = &storepb.UserSetting_General{
242					General: &storepb.GeneralUserSetting{
243						Locale:         general.Locale,
244						MemoVisibility: general.MemoVisibility,
245						Theme:          general.Theme,
246					},
247				}
248			} else {
249				return nil, errors.Errorf("general setting is required")
250			}
251		case storepb.UserSetting_WEBHOOKS:
252			if webhooks := apiSetting.GetWebhooksSetting(); webhooks != nil {
253				storeWebhooks := make([]*storepb.WebhooksUserSetting_Webhook, 0, len(webhooks.Webhooks))
254				for _, webhook := range webhooks.Webhooks {
255					storeWebhook := &storepb.WebhooksUserSetting_Webhook{
256						Id:    extractWebhookIDFromName(webhook.Name),
257						Title: webhook.DisplayName,
258						Url:   webhook.Url,
259					}
260					storeWebhooks = append(storeWebhooks, storeWebhook)
261				}
262				storeSetting.Value = &storepb.UserSetting_Webhooks{
263					Webhooks: &storepb.WebhooksUserSetting{
264						Webhooks: storeWebhooks,
265					},
266				}
267			} else {
268				return nil, errors.Errorf("webhooks setting is required")
269			}
270		case storepb.UserSetting_TAGS:
271			if tags := apiSetting.GetTagsSetting(); tags != nil {
272				storeSetting.Value = &storepb.UserSetting_Tags{
273					Tags: convertUserTagsSettingToStore(tags),
274				}
275			} else {
276				return nil, errors.Errorf("tags setting is required")
277			}
278		default:
279			return nil, errors.Errorf("unsupported setting key: %v", key)
280		}
281	
282		return storeSetting, nil
283	}
284	
285	// extractWebhookIDFromName extracts webhook ID from resource name.
286	// e.g., "users/123/webhooks/webhook-id" -> "webhook-id".
